/**
 * Pure 3D CGI Video Composition Engine
 * Remotion composition orchestrating:
 * - 3D CGI Multimodal Keyframes (generated by gemini-3-pro-image)
 * - Volumetric depth camera motion (push-in, pan, dramatic tilt, macro zooms)
 * - Word-by-word kinetic subtitles with ai33.pro millisecond timestamps
 * - Audio ducking: Narration voice + ducked Lyria 3.5 score (-8dB)
 */

import React from 'react';
import {
  AbsoluteFill,
  Audio,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';
import {
  Pure3DStudioProject,
  RenderedShot,
  WordTimestamp,
} from '@studio/types';

export interface Pure3DCompositionProps {
  project: Pure3DStudioProject;
  enableSubtitles?: boolean;
}

export const Pure3DComposition: React.FC<Pure3DCompositionProps> = ({
  project,
  enableSubtitles = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();

  const currentTimeMs = (frame / fps) * 1000;
  const shots = project.shots || [];
  const narration = project.narration;
  const soundtrack = project.soundtrack;

  // Calculate cumulative timeline for shots
  let accumulatedMs = 0;
  let activeShot: RenderedShot | null = null;
  let shotLocalFrame = 0;
  let shotTotalFrames = 30 * 5;

  for (let i = 0; i < shots.length; i++) {
    const s = shots[i]!;
    const shotDurationMs = (s.durationSeconds || 6) * 1000;
    const shotStartMs = accumulatedMs;
    const shotEndMs = accumulatedMs + shotDurationMs;

    if (currentTimeMs >= shotStartMs && (currentTimeMs < shotEndMs || i === shots.length - 1)) {
      activeShot = s;
      const shotStartFrame = Math.round((shotStartMs / 1000) * fps);
      shotLocalFrame = frame - shotStartFrame;
      shotTotalFrames = Math.max(1, Math.round((shotDurationMs / 1000) * fps));
      break;
    }
    accumulatedMs = shotEndMs;
  }

  // Camera Motion Interpolation (Volumetric Parallax simulation)
  const motion = activeShot?.cameraTrajectory?.motion || 'push-in';
  let scale = 1.0;
  let translateX = 0;
  let translateY = 0;
  let rotateZ = 0;

  if (motion === 'push-in') {
    scale = interpolate(shotLocalFrame, [0, shotTotalFrames], [1.0, 1.15], {
      extrapolateRight: 'clamp',
    });
  } else if (motion === 'slow-pan-right') {
    scale = 1.08;
    translateX = interpolate(shotLocalFrame, [0, shotTotalFrames], [-30, 30], {
      extrapolateRight: 'clamp',
    });
  } else if (motion === 'slow-pan-left') {
    scale = 1.08;
    translateX = interpolate(shotLocalFrame, [0, shotTotalFrames], [30, -30], {
      extrapolateRight: 'clamp',
    });
  } else if (motion === 'dramatic-tilt') {
    scale = 1.1;
    translateY = interpolate(shotLocalFrame, [0, shotTotalFrames], [20, -20], {
      extrapolateRight: 'clamp',
    });
    rotateZ = interpolate(shotLocalFrame, [0, shotTotalFrames], [-1.5, 1.5], {
      extrapolateRight: 'clamp',
    });
  } else if (motion === 'orbit-arc') {
    scale = 1.12;
    rotateZ = interpolate(shotLocalFrame, [0, shotTotalFrames], [-2, 2], {
      extrapolateRight: 'clamp',
    });
    translateX = interpolate(shotLocalFrame, [0, shotTotalFrames], [-20, 20], {
      extrapolateRight: 'clamp',
    });
  }

  // Find active word for kinetic typography
  const timestamps: WordTimestamp[] = narration?.timestamps || [];
  let activeWordIndex = -1;
  for (let i = 0; i < timestamps.length; i++) {
    const t = timestamps[i]!;
    if (currentTimeMs >= t.startMs && currentTimeMs <= t.endMs) {
      activeWordIndex = i;
      break;
    }
  }

  let visibleWords: { word: string; isActive: boolean; index: number }[] = [];
  if (activeWordIndex !== -1) {
    const windowStart = Math.max(0, activeWordIndex - 2);
    const windowEnd = Math.min(timestamps.length, activeWordIndex + 3);
    visibleWords = timestamps.slice(windowStart, windowEnd).map((t, idx) => ({
      word: t.word,
      isActive: windowStart + idx === activeWordIndex,
      index: windowStart + idx,
    }));
  } else if (activeShot) {
    const beat = project.beats.find((b) => b.beatNumber === activeShot?.beatNumber);
    if (beat) {
      const words = beat.text.split(' ');
      visibleWords = words.slice(0, 6).map((w, idx) => ({
        word: w,
        isActive: false,
        index: idx,
      }));
    }
  }

  return (
    <AbsoluteFill style={{ backgroundColor: '#030712', overflow: 'hidden' }}>
      {/* 1. 3D CGI Visual Shot Layer */}
      {activeShot && (
        <AbsoluteFill
          style={{
            transform: `scale(${scale}) translate(${translateX}px, ${translateY}px) rotate(${rotateZ}deg)`,
            transformOrigin: 'center center',
          }}
        >
          <img
            src={activeShot.imageUrl}
            alt={`Shot ${activeShot.beatNumber}`}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
            }}
          />
        </AbsoluteFill>
      )}

      {/* 2. Cinematic Vignette */}
      <AbsoluteFill
        style={{
          background:
            'radial-gradient(ellipse at center, transparent 40%, rgba(3, 7, 18, 0.65) 100%)',
          pointerEvents: 'none',
        }}
      />

      {/* 3. Word-by-Word Kinetic Subtitle Overlay */}
      {enableSubtitles && visibleWords.length > 0 && (
        <div
          style={{
            position: 'absolute',
            bottom: project.aspectRatio === '9:16' ? height * 0.18 : height * 0.12,
            left: 0,
            right: 0,
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            flexWrap: 'wrap',
            gap: project.aspectRatio === '9:16' ? '12px' : '16px',
            padding: '0 40px',
            zIndex: 50,
          }}
        >
          <div
            style={{
              backgroundColor: 'rgba(0, 0, 0, 0.72)',
              backdropFilter: 'blur(8px)',
              padding: '16px 28px',
              borderRadius: '20px',
              border: '2px solid rgba(212, 175, 55, 0.4)',
              boxShadow: '0 8px 32px rgba(0, 0, 0, 0.8)',
              display: 'flex',
              flexWrap: 'wrap',
              justifyContent: 'center',
              gap: '12px',
            }}
          >
            {visibleWords.map((item) => (
              <span
                key={item.index}
                style={{
                  fontFamily: 'Montserrat, Impact, "Arial Black", sans-serif',
                  fontSize: project.aspectRatio === '9:16' ? '38px' : '32px',
                  fontWeight: 900,
                  textTransform: 'uppercase',
                  letterSpacing: '1px',
                  color: item.isActive ? '#FBBF24' : '#F9FAFB',
                  transform: item.isActive ? 'scale(1.18)' : 'scale(1.0)',
                  transition: 'transform 0.12s ease-out, color 0.12s ease-out',
                  textShadow: item.isActive
                    ? '0 0 20px rgba(251, 191, 36, 0.9), 0 4px 8px #000'
                    : '0 2px 4px #000',
                  display: 'inline-block',
                }}
              >
                {item.word}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* 4. Audio Narration (ai33.pro) */}
      {narration?.audioUrl && (
        <Audio
          src={narration.audioUrl}
          volume={1.0}
        />
      )}

      {/* 5. Adaptive Soundtrack Score (Lyria 3.5) with Dynamic Ducking */}
      {soundtrack?.audioUrl && (
        <Audio
          src={soundtrack.audioUrl}
          volume={(f) => {
            const timeMs = (f / fps) * 1000;
            const isSpeaking = timestamps.some(
              (t) => timeMs >= t.startMs && timeMs <= t.endMs
            );
            return isSpeaking ? 0.18 : 0.65;
          }}
        />
      )}
    </AbsoluteFill>
  );
};
